const HUD_HOTBAR_MIN_WIDTH: u32 = HotbarLayout::TOTAL_WIDTH as u32;

/// Scale one logical-pixel layout rectangle at the physical output boundary.
///
/// HUD geometry is authored and intersected in logical pixels; embedding
/// renderers call this only when converting the final rectangle to physical
/// pixels so drawing, hit testing, occupancy reservations, and overlay
/// placement cannot drift through independently scaled intermediates.
pub fn logical_rect_to_physical(rect: UiRect, scale: i32) -> UiRect {
    let scale = scale.max(1);
    UiRect::new(
        rect.x * scale,
        rect.y * scale,
        (rect.w as i32 * scale).max(0) as u32,
        (rect.h as i32 * scale).max(0) as u32,
    )
}

/// Exact logical-pixel geometry of the Vanilla 1.21.1 HUD hotbar.
///
/// Every rectangle is derived from [`crate::vanilla_metrics`], so the
/// painter, the hit/occupancy mirror and the textured sprite blit cannot
/// disagree: the strip is `182×22` at `(w/2 - 91, h - 22)`, its nine
/// selectable cells advance on a 20-pixel pitch, each cell carries a
/// `16×16` item icon inset by 3, the moving highlight is a `24×23` frame
/// overhanging its cell by one pixel, and the offhand frame is `29×24` at
/// `(w/2 - 120, h - 23)`.
///
/// Convert with [`logical_rect_to_physical`] only at the output boundary.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HotbarLayout {
    w: i32,
    h: i32,
}

impl HotbarLayout {
    /// Hotbar cell pitch in logical pixels.
    pub const SLOT_PITCH: i32 = vm::HOTBAR_SLOT_PITCH;
    /// Number of selectable hotbar cells.
    pub const SLOT_COUNT: usize = vm::HOTBAR_SLOT_COUNT;
    /// Width of the nine-slot hotbar strip.
    pub const HOTBAR_WIDTH: i32 = vm::HOTBAR_WIDTH;
    /// Height of the nine-slot hotbar strip.
    pub const HOTBAR_HEIGHT: i32 = vm::HOTBAR_HEIGHT;
    /// Width of the complete offhand + hotbar reservation.
    pub const TOTAL_WIDTH: i32 = vm::HOTBAR_BLOCK_WIDTH;
    /// Logical px reserved along the bottom edge for the hotbar row;
    /// vitals, mount bars and chat chrome all stack above it.
    pub const RESERVE: i32 = vm::HOTBAR_RESERVE;

    /// Anchor the hotbar block in a logical-pixel viewport.
    pub const fn new(logical_width: i32, logical_height: i32) -> Self {
        Self {
            w: logical_width,
            h: logical_height,
        }
    }

    /// Left x of hotbar slot zero (`w/2 - 91`), in logical pixels.
    pub const fn x0(self) -> i32 {
        vm::hotbar_x(self.w)
    }

    /// Top y of every hotbar cell (`h - 22`), in logical pixels.
    pub const fn y0(self) -> i32 {
        vm::hotbar_y(self.h)
    }

    /// Rectangle of the textured nine-slot hotbar strip, in logical pixels.
    pub const fn panel_rect(self) -> UiRect {
        UiRect::new(
            self.x0(),
            self.y0(),
            Self::HOTBAR_WIDTH as u32,
            Self::HOTBAR_HEIGHT as u32,
        )
    }

    /// Rectangle of the offhand frame (`29×24`) on the default left side.
    pub const fn offhand_rect(self) -> UiRect {
        Self::offhand_frame(vm::offhand_left_x(self.w), self.h)
    }

    /// Mirror of [`offhand_rect`](Self::offhand_rect) for a left-handed
    /// player: vanilla docks the frame on the hotbar's right edge.
    pub const fn offhand_rect_right(self) -> UiRect {
        Self::offhand_frame(vm::offhand_right_x(self.w), self.h)
    }

    const fn offhand_frame(x: i32, h: i32) -> UiRect {
        UiRect::new(
            x,
            vm::offhand_y(h),
            vm::OFFHAND_W as u32,
            vm::OFFHAND_H as u32,
        )
    }

    /// Rectangle of hotbar slot `index` (`20×20`), in logical pixels.
    pub const fn slot_rect(self, index: usize) -> UiRect {
        UiRect::new(
            vm::hotbar_slot_x(self.w, index),
            self.y0(),
            Self::SLOT_PITCH as u32,
            Self::SLOT_PITCH as u32,
        )
    }

    /// Rectangle of the `16×16` item icon inside hotbar slot `index`.
    pub const fn item_rect(self, index: usize) -> UiRect {
        UiRect::new(
            vm::hotbar_item_x(self.w, index),
            vm::hotbar_item_y(self.h),
            vm::HOTBAR_ITEM_SIZE as u32,
            vm::HOTBAR_ITEM_SIZE as u32,
        )
    }

    /// Rectangle of the moving selection highlight over slot `index`
    /// (`24×23`, one pixel of overhang on every bordered side).
    pub const fn selection_rect(self, index: usize) -> UiRect {
        UiRect::new(
            vm::hotbar_select_x(self.w, index),
            vm::hotbar_select_y(self.h),
            vm::HOTBAR_SELECT_W as u32,
            vm::HOTBAR_SELECT_H as u32,
        )
    }

    /// Complete reserved block: the offhand frame plus the hotbar strip.
    ///
    /// The vanilla offhand frame is 24 px tall starting at `h - 23`, so its
    /// bottom row falls outside the viewport and the shipped sprite blit is
    /// clipped there; the reservation reports the visible height so overlay
    /// placement never claims a rectangle no draw command can reach.
    pub const fn occupied_rect(self) -> UiRect {
        let y = vm::offhand_y(self.h);
        // `Ord::clamp`/`min`/`max` are not const, so clamp by hand.
        let room = self.h - y;
        let visible = if room >= vm::OFFHAND_H {
            vm::OFFHAND_H
        } else if room < 0 {
            0
        } else {
            room
        };
        UiRect::new(
            vm::offhand_left_x(self.w),
            y,
            Self::TOTAL_WIDTH as u32,
            visible as u32,
        )
    }
}

/// Horizontal anchoring for one row of vital icons.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum VitalRowAlign {
    /// Icons advance rightwards from `x`.
    Left,
    /// Icons advance leftwards from the exclusive right edge `x`.
    Right,
}

/// Logical-pixel geometry for one vanilla vital-icon row.
///
/// Vanilla sprites are 9×9 pixels on an 8-pixel pitch, so adjacent
/// transparent edges overlap by one pixel. The procedural fallback occupies
/// the inner 8×8 cell. Right-aligned rows keep the historical anchor
/// `right - 8 - index * 8` exactly; changing that anchor would shift the
/// hunger, mount-health, and air rows by a pixel.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct VitalRow {
    x: i32,
    y: i32,
    align: VitalRowAlign,
}

impl VitalRow {
    /// Distance between adjacent icon cell origins.
    pub const ICON_PITCH: i32 = 8;
    /// Procedural/occupancy cell edge.
    pub const CELL_SIZE: i32 = 8;
    /// Textured sprite edge (sprites intentionally overlap by one pixel).
    pub const SPRITE_SIZE: i32 = 9;
    /// Maximum vanilla icons in one row.
    pub const MAX_ICONS: i32 = 10;
    /// Width reserved for a full row in collision calculations.
    pub const OCCUPIED_WIDTH: i32 = Self::ICON_PITCH * Self::MAX_ICONS;

    /// Left-anchored row starting at `(x, y)`.
    pub const fn left(x: i32, y: i32) -> Self {
        Self {
            x,
            y,
            align: VitalRowAlign::Left,
        }
    }

    /// Right-anchored row whose exclusive right edge is `right`.
    pub const fn right(right: i32, y: i32) -> Self {
        Self {
            x: right,
            y,
            align: VitalRowAlign::Right,
        }
    }

    /// Top y shared by every icon in this row.
    pub const fn y(self) -> i32 {
        self.y
    }

    /// Left x of icon `index` using the row's 8-pixel pitch.
    pub const fn icon_x(self, index: usize) -> i32 {
        let i = index as i32;
        match self.align {
            VitalRowAlign::Left => self.x + i * Self::ICON_PITCH,
            VitalRowAlign::Right => self.x - Self::CELL_SIZE - i * Self::ICON_PITCH,
        }
    }

    /// Logical sprite rectangle for icon `index` (9×9).
    pub const fn sprite_rect(self, index: usize) -> UiRect {
        UiRect::new(
            self.icon_x(index),
            self.y,
            Self::SPRITE_SIZE as u32,
            Self::SPRITE_SIZE as u32,
        )
    }

    /// Logical procedural-cell rectangle for icon `index` (8×8).
    pub const fn cell_rect(self, index: usize) -> UiRect {
        UiRect::new(
            self.icon_x(index),
            self.y,
            Self::CELL_SIZE as u32,
            Self::CELL_SIZE as u32,
        )
    }

    /// Whether this row is right-aligned.
    pub const fn is_right_aligned(self) -> bool {
        matches!(self.align, VitalRowAlign::Right)
    }
}

fn normalized_max_health(max_health: f32) -> f32 {
    if max_health.is_finite() && max_health > 0.0 {
        max_health
    } else {
        20.0
    }
}

/// Shared vital-row layout derived once from the HUD state and viewport.
///
/// Both the painter and the occupied-rectangle mirror consume this geometry;
/// the painter uses the individual rows while the collision model uses the
/// conservative full-width column spans and top edges.
#[derive(Clone, Copy, Debug)]
struct HudVitalsGeometry {
    left_x: i32,
    right_x: i32,
    base_y: i32,
    upper_y: i32,
    health_rows: i32,
    mount_rows: i32,
    has_absorption: bool,
    has_air: bool,
}

impl HudVitalsGeometry {
    /// Vertical distance between stacked rows of the same icon family.
    const ROW_STEP: i32 = 10;

    /// Anchor the vitals on the vanilla rows: hearts and food share
    /// `y = h - 39`, armor and air share `y = h - 49`, hearts start at
    /// `x = w/2 - 91` and food ends at `x = w/2 + 91`. Extra health,
    /// absorption, mount and air rows stack upward from those anchors.
    fn new(hud: &HudState, w: i32, h: i32) -> Self {
        let health_rows = (normalized_max_health(hud.max_health) / 20.0).ceil() as i32;
        let mount_rows = hud
            .mount_health
            .map(|(_, max)| ((max.max(1.0) / 20.0).ceil() as i32).clamp(1, 3))
            .unwrap_or(0);
        Self {
            left_x: vm::vitals_left_x(w),
            right_x: vm::vitals_right_x(w),
            base_y: vm::vitals_bottom_row_y(h),
            upper_y: vm::vitals_upper_row_y(h),
            health_rows,
            mount_rows,
            has_absorption: hud.absorption > 0.0,
            has_air: hud.air < 300,
        }
    }

    fn health_row(self, row: i32) -> VitalRow {
        VitalRow::left(self.left_x, self.base_y - row * Self::ROW_STEP)
    }

    fn armor_row(self) -> VitalRow {
        VitalRow::left(self.left_x, self.upper_y)
    }

    fn absorption_row(self) -> Option<VitalRow> {
        self.has_absorption.then(|| {
            let armor = self.armor_row();
            VitalRow::left(self.left_x, armor.y() - Self::ROW_STEP)
        })
    }

    fn hunger_row(self) -> VitalRow {
        VitalRow::right(self.right_x, self.base_y)
    }

    fn mount_row(self, row: i32) -> VitalRow {
        VitalRow::right(self.right_x, self.upper_y - row * Self::ROW_STEP)
    }

    fn air_row(self) -> Option<VitalRow> {
        self.has_air.then(|| {
            VitalRow::right(
                self.right_x,
                self.upper_y - self.mount_rows * Self::ROW_STEP,
            )
        })
    }

    fn column_ranges(self) -> (std::ops::Range<i32>, std::ops::Range<i32>) {
        (
            self.left_x..(self.left_x + VitalRow::OCCUPIED_WIDTH),
            (self.right_x - VitalRow::OCCUPIED_WIDTH)..self.right_x,
        )
    }

    fn left_top(self) -> i32 {
        let mut top = self
            .armor_row()
            .y()
            .min(self.base_y - (self.health_rows - 1).max(0) * Self::ROW_STEP);
        if let Some(absorption) = self.absorption_row() {
            top = top.min(absorption.y());
        }
        top
    }

    fn right_top(self) -> i32 {
        let mut top = self
            .base_y
            .min(self.base_y - (self.mount_rows - 1).max(0) * Self::ROW_STEP);
        if let Some(air) = self.air_row() {
            top = top.min(air.y());
        }
        top
    }

    fn bottom(self) -> i32 {
        self.base_y.max(self.upper_y) + VitalRow::CELL_SIZE
    }
}

/// Build the frame for the current screen: `(draw_list, hit_regions)`.
/// `width`/`height` are physical pixels.
pub fn layout_screen(state: &UiState, width: u32, height: u32) -> (UiDrawList, Vec<HitRegion>) {
    let mut list = UiDrawList::new();
    let mut regions = Vec::new();
    layout_screen_into(state, width, height, &mut list, &mut regions);
    (list, regions)
}

/// Buffer-reusing [`layout_screen`]: `out` is
/// [`UiDrawList::clear`]ed (recycling `Text` payload buffers) and
/// `regions` is cleared, then both are refilled — the caller's buffers
/// keep their heap capacity across frames.
pub fn layout_screen_into(
    state: &UiState,
    width: u32,
    height: u32,
    out: &mut UiDrawList,
    regions: &mut Vec<HitRegion>,
) {
    layout_screen_into_with_gui_atlas(state, width, height, out, regions, None);
}

/// [`layout_screen_into`] plus the host's optional GUI sprite atlas. HUD
/// elements bind stable logical sprite rectangles when present and keep
/// their procedural vectors when any individual sprite is absent.
pub fn layout_screen_into_with_gui_atlas(
    state: &UiState,
    width: u32,
    height: u32,
    out: &mut UiDrawList,
    regions: &mut Vec<HitRegion>,
    gui_atlas: Option<&GuiSpriteAtlas>,
) {
    out.clear();
    regions.clear();
    let ctx = build_ctx(
        state,
        width,
        height,
        std::mem::take(out),
        std::mem::take(regions),
        gui_atlas,
    );
    *out = ctx.list;
    *regions = ctx.regions;
}

/// Audit surface for tests and tooling: build the frame for
/// `state.screen` at `width`×`height` and report every button/tab
/// caption that had to be clipped to fit its rect
/// (`"WidgetId: <intended label>"` entries). An empty list means every
/// player-facing caption renders whole at that resolution.
pub fn truncated_widget_labels(state: &UiState, width: u32, height: u32) -> Vec<String> {
    build_ctx(state, width, height, UiDrawList::new(), Vec::new(), None).truncated
}

/// Shared frame builder behind [`layout_screen_into`] and
/// [`truncated_widget_labels`]: lays out `state.screen` (+ any modal)
/// and returns the whole context.
fn build_ctx<'a>(
    state: &'a UiState,
    width: u32,
    height: u32,
    list: UiDrawList,
    regions: Vec<HitRegion>,
    gui_atlas: Option<&'a GuiSpriteAtlas>,
) -> Ctx<'a> {
    let s = layout_scale(state, width, height);
    let mut ctx = Ctx {
        list,
        regions,
        hud_scratch: String::new(),
        truncated: Vec::new(),
        // Vanilla rounds the logical viewport UP (ceil(w/s), ceil(h/s));
        // `phys` clips the resulting 1..s-1 px overflow on the edges.
        w: (width.min(i32::MAX as u32) as i32 + s - 1) / s,
        h: (height.min(i32::MAX as u32) as i32 + s - 1) / s,
        pw: width,
        ph: height,
        s,
        lang: state.lang(),
        state,
        gui_atlas,
        band_top: i32::MAX,
        clip_top: 0,
    };
    match state.screen {
        Screen::Title => title(&mut ctx),
        Screen::Singleplayer => singleplayer(&mut ctx),
        Screen::Multiplayer => multiplayer(&mut ctx),
        Screen::Settings(tab) => settings(&mut ctx, tab),
        Screen::AboutMegu => about_megu(&mut ctx),
        Screen::Friends => friends(&mut ctx),
        Screen::ModSyncConsent => mod_sync(&mut ctx),
        Screen::ModSyncPrompt => mod_sync_prompt(&mut ctx),
        Screen::ModManager => embedded_mod_manager(&mut ctx),
        Screen::RecipeBrowser => embedded_recipe_browser(&mut ctx),
        Screen::InGameHud => hud(&mut ctx),
        Screen::Death => death(&mut ctx),
        Screen::Disconnected => disconnected(&mut ctx),
        Screen::Pause => pause(&mut ctx),
        Screen::CrashRecovery => crash(&mut ctx),
    }
    if state.modal.is_some() {
        ctx.regions.clear();
        modal(&mut ctx);
    }
    ctx
}

/// Resolve the requested GUI scale for this frame — every layout and
/// overlay routes through the canonical vanilla port
/// [`compute_gui_scale`], so menus, HUD chrome, toasts and editors all
/// snap to the same grid. The in-game hotbar needs
/// [`HotbarLayout::TOTAL_WIDTH`] logical pixels for the offhand gap and
/// all nine slots; cap its scale when a narrow viewport cannot hold that
/// complete row.
fn layout_scale(state: &UiState, width: u32, height: u32) -> i32 {
    let requested = compute_gui_scale(width, height, u32::from(state.ui_scale)) as i32;
    if state.screen == Screen::InGameHud {
        let width_limit = (width / HUD_HOTBAR_MIN_WIDTH).max(1) as i32;
        requested.min(width_limit)
    } else {
        requested
    }
}

// ---------------------------------------------------------------------------
// Layout context + widget helpers (all units logical px, scaled on emit)
// ---------------------------------------------------------------------------

struct Ctx<'a> {
    list: UiDrawList,
    regions: Vec<HitRegion>,
    hud_scratch: String,
    /// Button/tab captions that had to be clipped to fit their rect —
    /// collected for [`truncated_widget_labels`]; always-empty means no
    /// player-facing label truncates.
    truncated: Vec<String>,
    w: i32,
    h: i32,
    /// Physical-pixel viewport for the embedded sub-screens (they take
    /// raw framebuffer dims, not logical px).
    pw: u32,
    ph: u32,
    s: i32,
    lang: UiLang,
    state: &'a UiState,
    gui_atlas: Option<&'a GuiSpriteAtlas>,
    /// Reserved band top (logical px): content widgets that would cross
    /// it are dropped entirely so they can never collide with footer
    /// chrome. `i32::MAX` disables the band.
    band_top: i32,
    /// Top edge of a scrolling content viewport. Interactive widgets
    /// above it are dropped so scrolled content cannot collide with the
    /// fixed tab/header strip. Zero disables the extra clipping.
    clip_top: i32,
}

/// Logical-px rect shorthand for widget call sites.
const fn lr(x: i32, y: i32, w: i32, h: i32) -> UiRect {
    UiRect::new(
        x,
        y,
        if w < 0 { 0 } else { w as u32 },
        if h < 0 { 0 } else { h as u32 },
    )
}

impl Ctx<'_> {
    /// Scale a logical rect to physical pixels, clipped to the
    /// framebuffer on the right/bottom. Odd dims (`ceil(w/s)` logical
    /// columns) map a fully-visible logical edge onto `w-1` overflow
    /// px, so the physical clip has to live here as well as in `vis`.
    fn phys(&self, r: UiRect) -> UiRect {
        let p = logical_rect_to_physical(r, self.s);
        UiRect::new(
            p.x,
            p.y,
            (p.right().min(self.pw as i32) - p.x).max(0) as u32,
            (p.bottom().min(self.ph as i32) - p.y).max(0) as u32,
        )
    }

    /// Intersect a logical rect with the viewport; `None` when nothing
    /// is left. Every rect-emitting helper routes through this so no
    /// command can land outside the framebuffer.
    fn vis(&self, r: UiRect) -> Option<UiRect> {
        let (x0, y0) = (r.x.max(0), r.y.max(0));
        let (x1, y1) = (r.right().min(self.w), r.bottom().min(self.h));
        if x1 <= x0 || y1 <= y0 {
            return None;
        }
        Some(UiRect::new(x0, y0, (x1 - x0) as u32, (y1 - y0) as u32))
    }

    fn fill(&mut self, x: i32, y: i32, w: i32, h: i32, color: UiColor) {
        if let Some(r) = self.vis(lr(x, y, w, h)) {
            self.list.fill_rect(self.phys(r), color);
        }
    }

    fn border(&mut self, x: i32, y: i32, w: i32, h: i32, color: UiColor) {
        if let Some(r) = self.vis(lr(x, y, w, h)) {
            self.list
                .border_rect(self.phys(r), color, self.s.max(1) as u32);
        }
    }

    /// Draw one stable logical HUD sprite. Returns `false` when the host
    /// atlas does not contain that key so callers emit their procedural
    /// fallback instead of an invisible sprite command.
    fn hud_sprite(&mut self, key: &str, x: i32, y: i32, w: i32, h: i32) -> bool {
        let Some(entry) = self.gui_atlas.and_then(|atlas| atlas.named_sprite(key)) else {
            return false;
        };
        if let Some(r) = self.vis(lr(x, y, w, h)) {
            self.list.texture_uv(self.phys(r), entry);
        }
        // The binding exists even when this frame clips it away; do not
        // draw fallback vectors underneath unrelated viewport content.
        true
    }

    /// Draw a pre-resolved sprite entry (used for cropped progress fills).
    fn hud_sprite_entry(
        &mut self,
        entry: crate::draw::GuiSpriteUv,
        x: i32,
        y: i32,
        w: i32,
        h: i32,
    ) {
        if let Some(r) = self.vis(lr(x, y, w, h)) {
            self.list.texture_uv(self.phys(r), entry);
        }
    }

    /// Textured progress bar: background sprite plus its fill cropped in
    /// source pixels to `frac`. Returns `false` when either sprite is
    /// missing from the host atlas so the caller emits its procedural
    /// fallback instead of an invisible bar.
    fn sprite_bar(&mut self, bg_key: &str, fill_key: &str, r: UiRect, frac: f32) -> bool {
        let Some((bg, fill)) = self
            .gui_atlas
            .and_then(|atlas| Some((atlas.named_sprite(bg_key)?, atlas.named_sprite(fill_key)?)))
        else {
            return false;
        };
        let (x, y, w, h) = (r.x, r.y, r.w as i32, r.h as i32);
        self.hud_sprite_entry(bg, x, y, w, h);
        let src_w = (fill.width as f32 * frac).round() as u32;
        let dst_w = ((w as f32) * frac).round() as i32;
        if src_w > 0 && dst_w > 0 {
            self.hud_sprite_entry(fill.subrect(0, 0, src_w, fill.height), x, y, dst_w, h);
        }
        true
    }

    fn text(&mut self, x: i32, y: i32, mult: u32, color: UiColor, s: &str) {
        if x < 0 || x >= self.w || y < self.clip_top || y + 8 * mult as i32 > self.h {
            return;
        }
        // Clip to whatever width remains in the viewport so a long label
        // can never spill past the right edge.
        let budget = ((self.w - x) / mult as i32).max(0) as usize;
        let s = crate::draw::first_px(s, budget);
        self.list
            .text_str(x * self.s, y * self.s, mult * self.s as u32, color, s);
    }

    /// Centered text: `cx` is the logical center x. Strings wider than
    /// the viewport are clipped so they still fit.
    fn ctext(&mut self, cx: i32, y: i32, mult: u32, color: UiColor, s: &str) {
        if y < self.clip_top || y + 8 * mult as i32 > self.h {
            return;
        }
        let budget = ((self.w - 8) / mult as i32).max(0) as usize;
        let s = crate::draw::first_px(s, budget);
        let w = text_width(s, mult * self.s as u32) as i32;
        self.list.text_str(
            (cx * self.s - w / 2).max(0),
            y * self.s,
            mult * self.s as u32,
            color,
            s,
        );
    }

    fn hud_text(&mut self, x: i32, y: i32, mult: u32, color: UiColor, text: &str, limit: usize) {
        self.hud_scratch.clear();
        write_hud_str(text, limit, &mut self.hud_scratch);
        self.paint_hud_text(x, y, mult, color, i32::MAX);
    }

    fn paint_hud_text(&mut self, x: i32, y: i32, mult: u32, color: UiColor, width: i32) {
        if x < 0 || x >= self.w || y < 0 || y + 8 * mult as i32 > self.h {
            return;
        }
        let budget = ((self.w - x).min(width) / mult as i32).max(0) as usize;
        let clipped = crate::draw::first_px(&self.hud_scratch, budget);
        self.list
            .text_str(x * self.s, y * self.s, mult * self.s as u32, color, clipped);
    }

    fn hud_ctext(&mut self, cx: i32, y: i32, mult: u32, color: UiColor, text: &str, limit: usize) {
        self.hud_scratch.clear();
        write_hud_str(text, limit, &mut self.hud_scratch);
        if y < 0 || y + 8 * mult as i32 > self.h {
            return;
        }
        let budget = ((self.w - 8) / mult as i32).max(0) as usize;
        let clipped = crate::draw::first_px(&self.hud_scratch, budget);
        let w = text_width(clipped, mult * self.s as u32) as i32;
        self.list.text_str(
            (cx * self.s - w / 2).max(0),
            y * self.s,
            mult * self.s as u32,
            color,
            clipped,
        );
    }

    fn centered_in(&self, cx: i32, y: i32, h: i32, s: &str, mult: u32) -> (i32, i32) {
        let scale = mult * self.s as u32;
        let w = text_width(s, scale) as i32;
        // 8*scale px tall glyphs inside h logical px.
        let ty = y + (h - 8 * mult as i32) / 2;
        (cx - w / 2 / self.s, ty)
    }

    /// Tighter half-width caption advance when a button runs out of room.
    fn condensed_width(text: &str) -> i32 {
        text.chars().map(Self::condensed_advance).sum()
    }

    fn condensed_advance(ch: char) -> i32 {
        let advance = crate::draw::glyph_advance(ch) as i32;
        if advance <= 8 { advance.min(6) } else { advance }
    }

    fn condensed_text(&mut self, x: i32, y: i32, color: UiColor, text: &str) {
        let mut cx = x;
        for ch in text.chars() {
            let mut buf = [0u8; 4];
            self.text(cx, y, 1, color, ch.encode_utf8(&mut buf));
            cx += Self::condensed_advance(ch);
        }
    }

    fn hovered(&self, id: WidgetId) -> bool {
        self.state.hover == Some(id) || self.state.focused() == Some(id)
    }

    /// Register `r` (logical px) as `id`'s interactive region. The
    /// physical rect is clamped to the viewport and dropped when nothing
    /// is left, so degenerate viewports never emit dead hitboxes.
    fn region(&mut self, id: WidgetId, r: UiRect) {
        let p = self.phys(r);
        let (x0, y0) = (p.x.max(0), p.y.max(0));
        let (x1, y1) = (
            p.right().min(self.pw as i32),
            p.bottom().min(self.ph as i32),
        );
        if x1 <= x0 || y1 <= y0 {
            return;
        }
        self.regions.push(HitRegion::new(
            id,
            UiRect::new(x0, y0, (x1 - x0) as u32, (y1 - y0) as u32),
        ));
    }

    /// A clickable button with label; `r` is in logical px. Buttons
    /// crossing the reserved band (settings footer) are not emitted.
    fn button(&mut self, id: WidgetId, r: UiRect, label: &str, enabled: bool) {
        if r.y < self.clip_top || r.bottom() > self.band_top {
            return;
        }
        self.button_unchecked(id, r, label, enabled);
    }

    /// Button emission without the reserved-band check — footer chrome.
    /// The rect is clipped to the logical viewport first so degenerate
    /// heights can never emit off-screen commands or dead regions.
    fn button_unchecked(&mut self, id: WidgetId, r: UiRect, label: &str, enabled: bool) {
        let (x0, y0) = (r.x.max(0), r.y.max(0));
        let (x1, y1) = (r.right().min(self.w), r.bottom().min(self.h));
        if x1 <= x0 || y1 <= y0 {
            return;
        }
        let (x, y, w, h) = (x0, y0, x1 - x0, y1 - y0);
        let hot = enabled && self.hovered(id);
        let sprite = if !enabled {
            megu_core::ui_contract::SpriteId::ButtonDisabled
        } else if hot {
            megu_core::ui_contract::SpriteId::ButtonHighlighted
        } else {
            megu_core::ui_contract::SpriteId::Button
        };
        let textured = self.gui_atlas.is_some_and(|atlas| atlas.has(sprite));
        if textured {
            self.list.sprite(self.phys(lr(x, y, w, h)), sprite);
        } else {
            let bg = if !enabled {
                pal::BUTTON_DISABLED
            } else if hot {
                pal::BUTTON_HOVER
            } else {
                pal::BUTTON
            };
            self.fill(x, y, w, h, bg);
            let edge = if hot {
                pal::BUTTON_BORDER_HOVER
            } else {
                pal::BUTTON_BORDER
            };
            self.border(x, y, w, h, edge);
            if enabled && w >= 4 && h >= 4 {
                // Subtle 3D bevel: light inner top/left edge, dark inner
                // bottom/right edge — crisp tactile depth on every button.
                let hi = if hot {
                    UiColor::rgba(255, 255, 255, 64)
                } else {
                    UiColor::rgba(255, 255, 255, 34)
                };
                self.fill(x + 1, y + 1, w - 2, 1, hi);
                self.fill(x + 1, y + 1, 1, h - 2, hi);
                let lo = UiColor::rgba(0, 0, 0, 75);
                self.fill(x + 1, y + h - 2, w - 2, 1, lo);
                self.fill(x + w - 2, y + 1, 1, h - 2, lo);
                // At-a-glance ON/OFF accent bar on the left inner edge so a
                // toggle's state scans without reading the caption.
                let toggle = if label.ends_with(": ON") {
                    Some(true)
                } else if label.ends_with(": OFF") {
                    Some(false)
                } else {
                    None
                };
                if let Some(on) = toggle {
                    let bar = if on {
                        pal::ACCENT
                    } else {
                        UiColor::rgba(160, 165, 178, 90)
                    };
                    self.fill(x + 2, y + 2, 3, h - 4, bar);
                }
            }
        }
        let fg = if enabled { pal::TEXT } else { pal::TEXT_DIM };
        let normal_width = text_width(label, 1) as i32;
        let condensed_width = Self::condensed_width(label);
        let budget = w - 8;
        let use_condensed = normal_width > budget && condensed_width <= budget;
        let clipped = if use_condensed {
            label
        } else {
            crate::draw::first_px(label, budget.max(0) as usize)
        };
        if clipped.len() != label.len() {
            self.truncated.push(format!("{id:?}: {label}"));
        }
        let ty = y + (h - 8) / 2;
        if use_condensed {
            let tx = x + (w - condensed_width) / 2;
            self.condensed_text(tx + 1, ty + 1, UiColor::rgba(0, 0, 0, 140), clipped);
            self.condensed_text(tx, ty, fg, clipped);
        } else {
            let (tx, ty) = self.centered_in(x + w / 2, y, h, clipped, 1);
            // 1-px drop shadow behind the caption for legibility.
            self.text(tx + 1, ty + 1, 1, UiColor::rgba(0, 0, 0, 140), clipped);
            self.text(tx, ty, 1, fg, clipped);
        }
        if enabled {
            self.region(id, r);
        }
    }

    /// A button always enabled.
    fn btn(&mut self, id: WidgetId, r: UiRect, label: &str) {
        self.button(id, r, label, true);
    }

    /// Horizontal slider with a draggable thumb knob and a centered
    /// "Label: value" caption.
    fn slider(&mut self, id: WidgetId, r: UiRect, frac: f32, label: &str) {
        if r.y < self.clip_top || r.bottom() > self.band_top {
            return;
        }
        let (x, y, w, h) = (r.x, r.y, r.w as i32, r.h as i32);
        let hot = self.hovered(id);
        self.fill(x, y, w, h, pal::BUTTON);
        self.progress(
            lr(x + 1, y + 1, w - 2, h - 2),
            frac,
            pal::ACCENT.with_alpha(160),
            UiColor::rgba(0, 0, 0, 60),
            if hot {
                pal::BUTTON_BORDER_HOVER
            } else {
                pal::BUTTON_BORDER
            },
        );
        if w >= 8 && h >= 4 {
            // The same subtle 3D bevel buttons get, so the track reads
            // as a raised control instead of a flat bar.
            let hi = if hot {
                UiColor::rgba(255, 255, 255, 64)
            } else {
                UiColor::rgba(255, 255, 255, 34)
            };
            self.fill(x + 1, y + 1, w - 2, 1, hi);
            self.fill(x + 1, y + 1, 1, h - 2, hi);
            let lo = UiColor::rgba(0, 0, 0, 75);
            self.fill(x + 1, y + h - 2, w - 2, 1, lo);
            self.fill(x + w - 2, y + 1, 1, h - 2, lo);
            // Crisp 4px thumb knob centered on the fill edge, with its
            // own top highlight / bottom shadow.
            let fill_edge = x + 2 + ((w - 4) as f32 * frac.clamp(0.0, 1.0)) as i32;
            let kx = (fill_edge - 2).clamp(x + 2, x + w - 6);
            self.fill(kx, y + 2, 4, h - 4, UiColor::rgb(226, 230, 240));
            self.fill(kx, y + 2, 4, 1, UiColor::rgba(255, 255, 255, 90));
            self.fill(kx, y + h - 3, 4, 1, UiColor::rgba(0, 0, 0, 90));
        }
        let clipped = crate::draw::first_px(label, (w - 8).max(0) as usize);
        if clipped.len() != label.len() {
            self.truncated.push(format!("{id:?}: {label}"));
        }
        let (tx, ty) = self.centered_in(x + w / 2, y, h, clipped, 1);
        self.text(tx + 1, ty + 1, 1, UiColor::rgba(0, 0, 0, 140), clipped);
        self.text(tx, ty, 1, pal::TEXT, clipped);
        self.region(id, r);
    }

    /// Editable text field.
    fn textfield(
        &mut self,
        id: WidgetId,
        r: UiRect,
        content: &str,
        focused: bool,
        placeholder: &str,
    ) {
        if r.y < self.clip_top || r.bottom() > self.band_top {
            return;
        }
        let (x, y, w, h) = (r.x, r.y, r.w as i32, r.h as i32);
        self.fill(x, y, w, h, UiColor::rgb(10, 11, 14));
        self.border(
            x,
            y,
            w,
            h,
            if focused {
                pal::BUTTON_BORDER_HOVER
            } else {
                pal::PANEL_BORDER
            },
        );
        let pad = 3;
        let ty = y + (h - 8) / 2;
        if content.is_empty() && !focused {
            self.text(x + pad, ty, 1, pal::TEXT_DIM, placeholder);
        } else {
            let shown = if focused {
                format!("{content}_")
            } else {
                content.to_string()
            };
            let max_px = (w - 2 * pad).max(0) as usize;
            let clipped = crate::draw::first_px(&shown, max_px);
            self.text(x + pad, ty, 1, pal::TEXT, clipped);
        }
        self.region(id, r);
    }

    /// Translucent edge vignette used in place of
    /// [`Ctx::menu_background`] while the host's rotating panorama is
    /// live: the frame edges fade to black so captions stay readable
    /// while the 3D backdrop shows through everywhere — every fill
    /// stays under full alpha.
    fn panorama_vignette(&mut self) {
        const BANDS: i32 = 6;
        /// Each edge's vignette spans 1/DEPTH of the frame height.
        const DEPTH: i32 = 5;
        for i in 0..BANDS {
            let y0 = self.h * i / (BANDS * DEPTH);
            let y1 = self.h * (i + 1) / (BANDS * DEPTH);
            let a = (112 * (BANDS - i) / BANDS) as u8;
            self.fill(0, y0, self.w, y1 - y0, UiColor::rgba(0, 0, 0, a));
            let by0 = self.h - y1;
            let by1 = self.h - y0;
            let a = (112 * (i + 1) / BANDS) as u8;
            self.fill(0, by0, self.w, by1 - by0, UiColor::rgba(0, 0, 0, a));
        }
    }

    /// Background gradient shared by menu screens: sixteen vertical
    /// bands interpolate [`pal::BACKGROUND_TOP`] →
    /// [`pal::BACKGROUND_BOTTOM`] so there is no seam across the middle.
    fn menu_background(&mut self) {
        const BANDS: i32 = 16;
        let (top, bottom) = (pal::BACKGROUND_TOP, pal::BACKGROUND_BOTTOM);
        for i in 0..BANDS {
            // t sweeps 0..=255 across the bands; round-to-nearest lerp.
            let t = (i as u32 * 255 + BANDS as u32 / 2) / (BANDS as u32 - 1);
            let lerp =
                |a: u8, b: u8| ((u32::from(a) * (255 - t) + u32::from(b) * t + 127) / 255) as u8;
            let band = UiColor::rgba(
                lerp(top.r, bottom.r),
                lerp(top.g, bottom.g),
                lerp(top.b, bottom.b),
                255,
            );
            let y0 = self.h * i / BANDS;
            let y1 = self.h * (i + 1) / BANDS;
            self.fill(0, y0, self.w, y1 - y0, band);
        }
    }

    fn panel(&mut self, x: i32, y: i32, w: i32, h: i32) {
        self.fill(x, y, w, h, pal::PANEL);
        self.border(x, y, w, h, pal::PANEL_BORDER);
    }

    /// Progress bar clipped to the viewport like `fill`/`border`.
    fn progress(&mut self, r: UiRect, frac: f32, fill: UiColor, back: UiColor, border: UiColor) {
        if let Some(r) = self.vis(r) {
            self.list
                .progress_bar(self.phys(r), frac, fill, back, border);
        }
    }
}

fn onoff(v: bool) -> &'static str {
    if v { "ON" } else { "OFF" }
}

/// `"Label: value"` caption shared by every cycled or numeric setting row.
fn value_label(lang: UiLang, en: &str, ja: &str, value: impl std::fmt::Display) -> String {
    format!("{}: {value}", tr(lang, en, ja))
}

/// `"Label: ON"` / `"Label: OFF"` caption shared by every toggle row.
fn toggle_label(lang: UiLang, en: &str, ja: &str, on: bool) -> String {
    value_label(lang, en, ja, onoff(on))
}

/// Visible row window of a fixed-height scrolling list panel:
/// `(visible rows, clamped first index)`. The pager chrome reserves one
/// extra row once the list overflows.
fn list_window(body_h: i32, row_h: i32, len: usize, scroll: usize) -> (usize, usize) {
    let mut visible = (body_h / row_h) as usize;
    if len > visible {
        visible = ((body_h - 18) / row_h).max(0) as usize;
    }
    (visible, scroll.min(len.saturating_sub(visible)))
}

impl Ctx<'_> {
    /// Accent-colored section header above a group of rows.
    fn section(&mut self, x: i32, y: i32, label: &str) {
        self.text(x, y, 1, pal::ACCENT, label);
    }

    /// One settings row of width `w`: a button plus its dirty marker.
    fn setting_row_w(
        &mut self,
        id: WidgetId,
        key: SettingKey,
        x: i32,
        y: i32,
        w: i32,
        label: &str,
    ) {
        self.btn(id, lr(x, y, w, 20), label);
        self.dirty_dot(key, x + w + 6, y + 6);
    }

    /// Standard 320px settings button row with its dirty marker.
    fn setting_row(&mut self, id: WidgetId, key: SettingKey, x: i32, y: i32, label: &str) {
        self.setting_row_w(id, key, x, y, 320, label);
    }

    /// Settings slider row occupying `r` (logical px) with its dirty
    /// marker just right of the track.
    fn slider_row_r(&mut self, id: WidgetId, key: SettingKey, r: UiRect, frac: f32, label: &str) {
        self.slider(id, r, frac, label);
        self.dirty_dot(key, r.x + r.w as i32 + 6, r.y + 6);
    }

    /// Standard 320px settings slider row.
    fn slider_row(
        &mut self,
        id: WidgetId,
        key: SettingKey,
        x: i32,
        y: i32,
        frac: f32,
        label: &str,
    ) {
        self.slider_row_r(id, key, lr(x, y, 320, 20), frac, label);
    }

    /// Button whose caption is one bilingual literal.
    fn tr_btn(&mut self, id: WidgetId, r: UiRect, en: &str, ja: &str) {
        self.btn(id, r, tr(self.lang, en, ja));
    }

    /// [`Ctx::tr_btn`] with an explicit enabled state.
    fn tr_button(&mut self, id: WidgetId, r: UiRect, en: &str, ja: &str, enabled: bool) {
        self.button(id, r, tr(self.lang, en, ja), enabled);
    }

    /// [`Ctx::tr_btn`] without the reserved-band check — footer chrome.
    fn tr_button_unchecked(&mut self, id: WidgetId, r: UiRect, en: &str, ja: &str) {
        self.button_unchecked(id, r, tr(self.lang, en, ja), true);
    }

    /// Up / `a-b` counter / Down pager chrome of one scrolling list
    /// panel, anchored to its `x`, `w` and row `y` in logical px.
    fn pager(
        &mut self,
        x: i32,
        w: i32,
        y: i32,
        up: WidgetId,
        down: WidgetId,
        span: (usize, usize),
    ) {
        let lang = self.lang;
        self.btn(up, lr(x + 4, y, 60, 16), tr(lang, "Up", "上"));
        self.ctext(
            x + w / 2,
            y + 4,
            1,
            pal::TEXT_DIM,
            &format!("{}-{}", span.0, span.1),
        );
        self.btn(down, lr(x + w - 64, y, 60, 16), tr(lang, "Down", "下"));
    }

    /// The `●` dirty marker drawn just right of a settings widget whose
    /// value differs from the session-open snapshot. Kept out of the
    /// widget label so button text stays byte-identical; off-viewport
    /// dots are dropped by [`Ctx::text`] like any other draw command.
    fn dirty_dot(&mut self, key: SettingKey, x: i32, y: i32) {
        if self.state.is_setting_dirty(key) {
            self.text(x, y, 1, pal::WARNING, "●");
        }
    }
}

// ---------------------------------------------------------------------------
// Title
// ---------------------------------------------------------------------------

/// Vanilla's title/pause button grid geometry: `(top, row step, height)`.
///
/// The column is anchored at [`vm::title_top`] (`h / 4 + 48`, the block
/// directly under the wordmark) with 24-pixel row steps and 20-pixel
/// buttons, exactly like the shipped screen. Tiny logical viewports squeeze
/// the step and the button height first and only then lift the column, so
/// the masthead and the version line always stay clear of it.
fn title_button_geometry(height: i32) -> (i32, i32, i32) {
    let step = vm::TITLE_ROW_STEP.min((height - 96) / 2).max(4);
    let button_height = vm::BUTTON_H.min(step);
    let top = vm::title_top(height)
        .min(height - 14 - 2 * step - 2 * button_height - 8)
        .max(34);
    (top, step, button_height)
}

/// Top of the Singleplayer button in logical pixels.
pub fn title_buttons_top(logical_height: u32) -> u32 {
    title_button_geometry(logical_height.min(i32::MAX as u32) as i32).0 as u32
}

fn title(ctx: &mut Ctx) {
    // A live host panorama replaces the painted gradient; only the
    // translucent edge vignette is drawn so captions stay readable.
    if ctx.state.title_panorama_active {
        ctx.panorama_vignette();
    } else {
        ctx.menu_background();
    }
    let lang = ctx.lang;
    let cx = ctx.w / 2;

    // The wordmark never truncates: explicit high GUI scales can make
    // the logical viewport narrower than the 3× text, so step the clean-
    // room text logo down before clipping it. The smaller form still reads
    // as the masthead and leaves the button grid untouched.
    let masthead_mult = if text_width("MINECRAFT", 3) as i32 + 8 <= ctx.w {
        3
    } else if text_width("MINECRAFT", 2) as i32 + 8 <= ctx.w {
        2
    } else {
        1
    };
    ctx.ctext(cx, 34, masthead_mult, pal::TEXT, "MINECRAFT");
    ctx.ctext(cx, 62, 1, pal::TEXT_DIM, "MEGU EDITION");

    // Vanilla 1.21.1 silhouette: a centered 200px column — two
    // full-width rows, then the 98 + 4 + 98 split pair — anchored at
    // `h / 4 + 48` under the wordmark and, after vanilla's 8px breathing
    // gap, the classic bottom row: a 20px language chip | Options | Quit
    // | a 20px About chip. Everything stays above the version line
    // (h-14); `step`/`bh` squeeze first.
    let (y, step, bh) = title_button_geometry(ctx.h);
    let sq = 20.min(bh);
    // Keep the language and About chips fully inside the logical
    // viewport. At compact resolutions with a large GUI scale, the
    // normal 200px column would push both corner chips off-screen.
    let max_column_width = ctx.w - 2 * (sq + 4);
    let bw = 200.min(max_column_width).max(24) & !1;
    let x = cx - bw / 2;
    let half = (bw - 4) / 2;
    ctx.btn(
        WidgetId::TitleSingleplayer,
        lr(x, y, bw, bh),
        ctx.state.translate(
            "menu.singleplayer",
            tr(lang, "Singleplayer", "シングルプレイ"),
        ),
    );
    ctx.btn(
        WidgetId::TitleMultiplayer,
        lr(x, y + step, bw, bh),
        ctx.state
            .translate("menu.multiplayer", tr(lang, "Multiplayer", "マルチプレイ")),
    );
    // Vanilla's Realms/Mods slot splits into two half-width buttons.
    let y3 = y + 2 * step;
    ctx.tr_btn(
        WidgetId::TitleMods,
        lr(x, y3, half, bh),
        "Mods&Packs",
        "Modとパック",
    );
    ctx.tr_btn(
        WidgetId::TitleFriends,
        lr(x + bw - half, y3, half, bh),
        "Friends",
        "フレンドと遊ぶ",
    );
    // Bottom row: the corner chips hang off the column ends exactly
    // where vanilla parks its globe and accessibility buttons.
    let y4 = y3 + bh + 8;
    icon_btn(
        ctx,
        WidgetId::TitleLanguage,
        lr(x - 4 - sq, y4, sq, sq),
        if lang == UiLang::Ja { "JA" } else { "EN" },
    );
    ctx.btn(
        WidgetId::TitleSettings,
        lr(x, y4, half, bh),
        ctx.state
            .translate("menu.options", tr(lang, "Options...", "設定...")),
    );
    ctx.btn(
        WidgetId::TitleQuit,
        lr(x + bw - half, y4, half, bh),
        ctx.state
            .translate("menu.quit", tr(lang, "Quit Game", "ゲームを終了")),
    );
    icon_btn(
        ctx,
        WidgetId::TitleAbout,
        lr(x + bw + 4, y4, sq, sq),
        tr(lang, "?", "？"),
    );

    ctx.text(
        vm::FOOTER_X,
        ctx.h - vm::FOOTER_Y_OFFSET,
        1,
        pal::TEXT,
        "Megu 1.21.1",
    );

    // Host-reported status/errors stay visible on the menu — a failed
    // singleplayer launch or multiplayer join never reads as a no-op.
    if let Some(status) = &ctx.state.title_status {
        ctx.hud_ctext(cx, ctx.h - 24, 1, pal::WARNING, status, 56);
    }
}

/// A compact square icon chip (vanilla's globe/accessibility buttons):
/// standard button chrome plus a centered caption allowed to span the
/// whole rect — the normal 8px label margin would clip a 2-glyph tag.
fn icon_btn(ctx: &mut Ctx, id: WidgetId, r: UiRect, label: &str) {
    if r.bottom() > ctx.band_top {
        return;
    }
    ctx.btn(id, r, "");
    let (tx, ty) = ctx.centered_in(r.x + r.w as i32 / 2, r.y, r.h as i32, label, 1);
    ctx.text(tx + 1, ty + 1, 1, UiColor::rgba(0, 0, 0, 140), label);
    ctx.text(tx, ty, 1, pal::TEXT, label);
}

// ---------------------------------------------------------------------------
// Singleplayer: world select + Create New World
// ---------------------------------------------------------------------------

fn singleplayer(ctx: &mut Ctx) {
    ctx.menu_background();
    let lang = ctx.lang;
    let cx = ctx.w / 2;

    ctx.ctext(
        cx,
        8,
        2,
        pal::TEXT,
        tr(lang, "Select World", "ワールドを選択"),
    );

    // Reserve the footer strip (status line + Back): list and create
    // widgets that would reach it are dropped by the helpers instead of
    // painting under the chrome.
    ctx.band_top = ctx.h - 44;

    let pw = 340.min(ctx.w - 8).max(40);
    let px = cx - pw / 2;

    // The create block anchors to the footer: label + name field + seed
    // field + mode row + commands row + button. The world list owns
    // what remains.
    let create_h = 122;
    let create_anchor = (ctx.band_top - 4 - create_h).max(36);
    let list_top = 34;
    let list_bottom = create_anchor - 4;
    let create_scroll = ctx
        .state
        .menu_scroll
        .singleplayer_create
        .min(ctx.state.active_menu_scroll_limit(ctx.w, ctx.h)) as i32;
    let create_top = create_anchor - create_scroll;

    // --- Saved worlds ------------------------------------------------
    let worlds = &ctx.state.singleplayer.worlds;
    ctx.panel(px, list_top, pw, (list_bottom - list_top).max(10));
    let row_h = 20;
    // Overflow reserves a one-row pager strip at the panel's bottom.
    let body_h = (list_bottom - list_top - 6).max(0);
    let mut visible = (body_h / row_h) as usize;
    if worlds.len() > visible {
        visible = ((body_h - 18) / row_h).max(0) as usize;
    }
    let scroll = ctx
        .state
        .singleplayer
        .scroll
        .min(worlds.len().saturating_sub(visible));
    if worlds.is_empty() {
        ctx.ctext(
            cx,
            list_top + 6,
            1,
            pal::TEXT_DIM,
            tr(lang, "No saved worlds yet", "ワールドはまだありません"),
        );
    }
    for row in 0..visible {
        let i = scroll + row;
        let Some(name) = worlds.get(i) else { break };
        ctx.btn(
            WidgetId::SingleplayerWorld(i),
            lr(px + 4, list_top + 4 + row as i32 * row_h, pw - 8, row_h - 2),
            &hud_str(name, ((pw - 20) / 8).max(4) as usize),
        );
    }
    // The pager needs real width (Up + Down + the range label) and a
    // full strip inside the list area; otherwise it is dropped — the
    // rows themselves stay clickable at any size.
    let py = list_top + 4 + visible as i32 * row_h;
    if worlds.len() > visible && pw >= 176 && py + 16 <= list_bottom {
        ctx.tr_btn(
            WidgetId::SingleplayerListUp,
            lr(px + 4, py, 60, 16),
            "Up",
            "上",
        );
        ctx.ctext(
            cx,
            py + 4,
            1,
            pal::TEXT_DIM,
            &format!("{}-{}", scroll + 1, (scroll + visible).min(worlds.len())),
        );
        ctx.tr_btn(
            WidgetId::SingleplayerListDown,
            lr(px + pw - 64, py, 60, 16),
            "Down",
            "下",
        );
    }

    // --- Create New World --------------------------------------------
    // Compact viewports scroll the create form beneath the fixed world
    // list/header. Widgets that cross the footer remain dropped until a
    // scroll step brings them fully into the safe band.
    ctx.clip_top = 30;
    ctx.ctext(
        cx,
        create_top,
        1,
        pal::ACCENT,
        tr(lang, "Create New World", "新しいワールド"),
    );
    ctx.textfield(
        WidgetId::SingleplayerNameField,
        lr(px, create_top + 12, pw, 18),
        &ctx.state.singleplayer.new_name,
        ctx.state.world_name_field_active(),
        tr(lang, "World Name", "ワールド名"),
    );
    ctx.textfield(
        WidgetId::SingleplayerSeedField,
        lr(px, create_top + 34, pw, 18),
        &ctx.state.singleplayer.seed_text,
        ctx.state.world_seed_field_active(),
        tr(lang, "Seed (optional)", "シード（オプション）"),
    );
    let mode = match ctx.state.singleplayer.game_mode {
        crate::state::SingleplayerGameMode::Survival => tr(lang, "Survival", "サバイバル"),
        crate::state::SingleplayerGameMode::Creative => tr(lang, "Creative", "クリエイティブ"),
        crate::state::SingleplayerGameMode::Hardcore => tr(lang, "Hardcore", "ハードコア"),
    };
    let difficulty = match ctx.state.singleplayer.difficulty {
        crate::state::SingleplayerDifficulty::Peaceful => tr(lang, "Peaceful", "ピースフル"),
        crate::state::SingleplayerDifficulty::Easy => tr(lang, "Easy", "イージー"),
        crate::state::SingleplayerDifficulty::Normal => tr(lang, "Normal", "ノーマル"),
        crate::state::SingleplayerDifficulty::Hard => tr(lang, "Hard", "ハード"),
    };
    ctx.btn(
        WidgetId::SingleplayerGameMode,
        lr(px, create_top + 56, pw / 2 - 2, 18),
        &format!("{}: {mode}", tr(lang, "Game Mode", "ゲームモード")),
    );
    ctx.btn(
        WidgetId::SingleplayerDifficulty,
        lr(px + pw / 2 + 2, create_top + 56, pw / 2 - 2, 18),
        &format!("{}: {difficulty}", tr(lang, "Difficulty", "難易度")),
    );
    // Vanilla's "Allow Commands" toggle — locked off (disabled chrome,
    // no hit region) while Hardcore is selected.
    let hardcore = ctx.state.singleplayer.game_mode
        == crate::state::SingleplayerGameMode::Hardcore;
    ctx.button(
        WidgetId::SingleplayerAllowCommands,
        lr(px, create_top + 78, pw, 18),
        &format!(
            "{}: {}",
            tr(lang, "Allow Commands", "コマンドを許可"),
            if ctx.state.singleplayer.effective_allow_commands() {
                "ON"
            } else {
                "OFF"
            }
        ),
        !hardcore,
    );
    ctx.tr_btn(
        WidgetId::SingleplayerCreate,
        lr(px, create_top + 100, pw, 18),
        "Create & Play",
        "作成してプレイ",
    );
    ctx.clip_top = 0;
    ctx.band_top = i32::MAX;

    // Status/errors (failed launches, validation rejections) render
    // right above Back — never silently dropped.
    if let Some(status) = &ctx.state.title_status {
        ctx.hud_ctext(cx, ctx.h - 41, 1, pal::WARNING, status, 56);
    }
    ctx.tr_button_unchecked(
        WidgetId::SingleplayerBack,
        lr(cx - 50, ctx.h - 30, 100, 20),
        "Back",
        "戻る",
    );
}

fn multiplayer(ctx: &mut Ctx) {
    ctx.menu_background();
    let lang = ctx.lang;
    let cx = ctx.w / 2;

    ctx.ctext(
        cx,
        8,
        2,
        pal::TEXT,
        tr(lang, "Play Multiplayer", "マルチプレイ"),
    );

    // Footer strip (status line + Back): like Singleplayer, widgets that
    // would reach it are dropped instead of painting under the chrome.
    ctx.band_top = ctx.h - 44;

    let pw = 340.min(ctx.w - 8).max(40);
    let px = cx - pw / 2;

    // The direct-connect block anchors to the footer: label + field +
    // button row = 66 logical px. Everything above it splits between the
    // "Friends & LAN" section (top) and the saved-server list.
    let direct_h = 66;
    let direct_top = (ctx.band_top - 4 - direct_h).max(36);
    let list_top = 30;
    let list_bottom = direct_top - 4;
    let avail = list_bottom - list_top;

    // --- Friends & LAN ------------------------------------------------
    // Friend-hosted worlds (1-click E2EE join) and LAN-discovered worlds
    // (direct join) share one panel — friends first, then LAN rows. The
    // section owns ~2/5 of the vertical space, capped so huge viewports
    // keep the saved list dominant.
    let fl_panel_h = ((avail * 2 / 5) - 12).clamp(24, 140);
    let fl_top = list_top + 12;
    let saved_label_y = fl_top + fl_panel_h + 4;
    let saved_top = saved_label_y + 10;
    let saved_bottom = list_bottom;

    ctx.section(px + 2, list_top, tr(lang, "Friends & LAN", "フレンドとLAN"));
    ctx.tr_btn(
        WidgetId::MultiplayerManageFriends,
        lr(px + pw - 120, list_top - 3, 120, 14),
        "Manage Friends",
        "フレンド管理",
    );

    let friend_worlds = &ctx.state.multiplayer.friend_worlds;
    let lan_worlds = &ctx.state.multiplayer.lan_worlds;
    let fl_total = friend_worlds.len() + lan_worlds.len();
    ctx.panel(px, fl_top, pw, fl_panel_h);
    let fl_row_h = 18;
    let (fl_visible, fl_scroll) = list_window(
        (fl_panel_h - 6).max(0),
        fl_row_h,
        fl_total,
        ctx.state.multiplayer.friend_lan_scroll,
    );
    if fl_total == 0 && fl_panel_h >= 22 {
        ctx.ctext(
            cx,
            fl_top + 8,
            1,
            pal::TEXT_DIM,
            tr(
                lang,
                "No friend or LAN worlds online",
                "オンラインのフレンド/LANワールドはありません",
            ),
        );
    }
    let fl_chars = ((pw - 20) / 8).max(4) as usize;
    for row in 0..fl_visible {
        let i = fl_scroll + row;
        let y = fl_top + 4 + row as i32 * fl_row_h;
        let r = lr(px + 4, y, pw - 8, fl_row_h - 2);
        if i < friend_worlds.len() {
            let entry = &friend_worlds[i];
            let label = format!(
                "{} — {} ({}/{})",
                entry.friend_name, entry.world_name, entry.online_players, entry.max_players
            );
            ctx.btn(
                WidgetId::MultiplayerFriendWorld(i),
                r,
                &hud_str(&label, fl_chars),
            );
        } else {
            let Some(entry) = lan_worlds.get(i - friend_worlds.len()) else {
                break;
            };
            let label = format!("LAN {} — {}:{}", entry.name, entry.address, entry.port);
            ctx.btn(
                WidgetId::MultiplayerLanWorld(i - friend_worlds.len()),
                r,
                &hud_str(&label, fl_chars),
            );
        }
    }
    let fl_py = fl_top + 4 + fl_visible as i32 * fl_row_h;
    if fl_total > fl_visible && pw >= 176 && fl_py + 16 <= fl_top + fl_panel_h {
        ctx.pager(
            px,
            pw,
            fl_py,
            WidgetId::MultiplayerFriendLanUp,
            WidgetId::MultiplayerFriendLanDown,
            (fl_scroll + 1, (fl_scroll + fl_visible).min(fl_total)),
        );
    }

    // --- Saved servers -----------------------------------------------
    if saved_bottom > saved_top + 8 {
        ctx.section(
            px + 2,
            saved_label_y,
            tr(lang, "Saved Servers", "保存したサーバー"),
        );
        let servers = &ctx.state.multiplayer.servers;
        ctx.panel(px, saved_top, pw, (saved_bottom - saved_top).max(10));
        let row_h = 20;
        let (visible, scroll) = list_window(
            (saved_bottom - saved_top - 6).max(0),
            row_h,
            servers.len(),
            ctx.state.multiplayer.scroll,
        );
        if servers.is_empty() {
            ctx.ctext(
                cx,
                saved_top + 6,
                1,
                pal::TEXT_DIM,
                tr(lang, "No saved servers", "サーバーはまだありません"),
            );
        }
        let selected = ctx.state.multiplayer.selected;
        for row in 0..visible {
            let i = scroll + row;
            let Some(entry) = servers.get(i) else { break };
            let r = lr(
                px + 4,
                saved_top + 4 + row as i32 * row_h,
                pw - 8,
                row_h - 2,
            );
            // Selected rows draw a highlight fill under the button row id.
            if selected == Some(i) {
                ctx.fill(r.x, r.y, r.w as i32, r.h as i32, pal::BUTTON_HOVER);
            }
            let label = format!("{} — {}:{}", entry.name, entry.address, entry.port);
            ctx.btn(
                WidgetId::MultiplayerServer(i),
                r,
                &hud_str(&label, ((pw - 20) / 8).max(4) as usize),
            );
        }
        let py = saved_top + 4 + visible as i32 * row_h;
        if servers.len() > visible && pw >= 176 && py + 16 <= saved_bottom {
            ctx.pager(
                px,
                pw,
                py,
                WidgetId::MultiplayerListUp,
                WidgetId::MultiplayerListDown,
                (scroll + 1, (scroll + visible).min(servers.len())),
            );
        }
    }

    // --- Direct connect / quick-add -----------------------------------
    ctx.ctext(
        cx,
        direct_top,
        1,
        pal::ACCENT,
        tr(lang, "Direct Connect", "直接接続"),
    );
    ctx.textfield(
        WidgetId::MultiplayerAddressField,
        lr(px, direct_top + 12, pw, 18),
        &ctx.state.multiplayer.address_text,
        ctx.state.multiplayer.address_field_active(),
        tr(lang, "host:port", "ホスト:ポート"),
    );
    let bw = ((pw - 8) / 3).max(24);
    let by = direct_top + 34;
    let actions = [
        (WidgetId::MultiplayerJoin, tr(lang, "Join", "参加")),
        (WidgetId::MultiplayerAdd, tr(lang, "Add", "追加")),
        (WidgetId::MultiplayerDelete, tr(lang, "Delete", "削除")),
    ];
    for (i, (id, label)) in actions.into_iter().enumerate() {
        ctx.btn(id, lr(px + i as i32 * (bw + 4), by, bw, 18), label);
    }
    ctx.band_top = i32::MAX;

    // Inline status (bad address, store failures, "select a server")
    // renders right above Back — never silently dropped.
    if let Some(status) = ctx
        .state
        .multiplayer
        .status
        .as_deref()
        .or(ctx.state.title_status.as_deref())
    {
        ctx.hud_ctext(cx, ctx.h - 41, 1, pal::WARNING, status, 56);
    }
    ctx.tr_button_unchecked(
        WidgetId::MultiplayerBack,
        lr(cx - 50, ctx.h - 30, 100, 20),
        "Back",
        "戻る",
    );
}

fn disconnected(ctx: &mut Ctx) {
    let lang = ctx.lang;
    let cx = ctx.w / 2;
    let state = &ctx.state.disconnected;

    ctx.menu_background();
    let ty = (ctx.h / 4).min(ctx.h.saturating_sub(16)).max(0);
    ctx.ctext(
        cx,
        ty,
        2,
        pal::DANGER,
        if state.title.is_empty() {
            tr(lang, "Disconnected", "切断されました")
        } else {
            &state.title
        },
    );
    if !state.reason.is_empty() {
        ctx.hud_ctext(cx, ty + 24, 1, pal::TEXT, &state.reason, 72);
    }
    let bw = 140.min(ctx.w - 12).max(24);
    ctx.tr_btn(
        WidgetId::DisconnectedBack,
        lr(cx - bw / 2, (ty + 44).min((ctx.h - 22).max(2)), bw, 20),
        "Back to Title",
        "タイトルへ戻る",
    );
}

/// The compact `Boot: N ms` telemetry badge on the About screen —
/// Megu's own surface, so the telemetry is welcome there; the vanilla
/// Title grid ships clean. Emitted only while
/// [`UiState::startup_timeline`] is populated *and* the badge can sit in
/// the bottom-right corner without ever reaching the centered widget
/// column (`clear` is the half-width to stay right of).
fn boot_badge(ctx: &mut Ctx, clear: i32) {
    let Some(timeline) = &ctx.state.startup_timeline else {
        return;
    };
    let label = format!("{}: {} ms", tr(ctx.lang, "Boot", "起動"), timeline.total_ms);
    let bw = (text_width(&label, 1) as i32 + 8).min(ctx.w - 8);
    let bx = ctx.w - 4 - bw;
    if bw < 24 || ctx.h < 30 || bx < ctx.w / 2 + clear {
        return;
    }
    ctx.btn(WidgetId::BootBadge, lr(bx, ctx.h - 26, bw, 12), &label);
}

// ---------------------------------------------------------------------------
// Settings
// ---------------------------------------------------------------------------

fn settings(ctx: &mut Ctx, active: SettingsTab) {
    ctx.menu_background();
    let lang = ctx.lang;
    let cx = ctx.w / 2;

    ctx.ctext(cx, 8, 2, pal::TEXT, tr(lang, "Settings", "設定"));

    // Tab strip: tabs shrink (never overflow) below ~480 logical px, and
    // the strip hugs the top edge when the window is too short to leave
    // the footer its own band.
    let gap = 4;
    let tw = 76
        .min(
            (ctx.w - 4 - gap * (SettingsTab::ALL.len() as i32 - 1)) / SettingsTab::ALL.len() as i32,
        )
        .max(10);
    // `None` below ~56px: the strip and the footer cannot coexist, and
    // the footer (Done) wins — tabs stay reachable via keyboard.
    let tab_y = if ctx.h < 56 {
        None
    } else if ctx.h < 96 {
        Some(4)
    } else {
        Some(30)
    };
    let total = SettingsTab::ALL.len() as i32 * (tw + gap) - gap;
    let mut tx = cx - total / 2;
    for tab in SettingsTab::ALL {
        let Some(tab_y) = tab_y else { break };
        let id = match tab {
            SettingsTab::Video => WidgetId::TabVideo,
            SettingsTab::Audio => WidgetId::TabAudio,
            SettingsTab::Shaders => WidgetId::TabShaders,
            SettingsTab::Qol => WidgetId::TabQol,
            SettingsTab::FairPlay => WidgetId::TabFairPlay,
            SettingsTab::Language => WidgetId::TabLanguage,
            SettingsTab::Controls => WidgetId::TabControls,
        };
        let is_active = tab == active;
        let hot = ctx.hovered(id);
        ctx.fill(
            tx,
            tab_y,
            tw,
            18,
            if is_active {
                pal::BUTTON_HOVER
            } else if hot {
                pal::BUTTON
            } else {
                pal::BUTTON_DISABLED
            },
        );
        ctx.border(tx, tab_y, tw, 18, pal::BUTTON_BORDER);
        if is_active {
            ctx.fill(tx, tab_y + 17, tw, 1, pal::ACCENT);
        }
        let label = crate::draw::first_px(tab.label(lang), (tw - 4).max(1) as usize);
        if label.len() != tab.label(lang).len() {
            ctx.truncated.push(format!("{id:?}: {}", tab.label(lang)));
        }
        let (lx, ly) = ctx.centered_in(tx + tw / 2, tab_y, 18, label, 1);
        ctx.text(lx + 1, ly + 1, 1, UiColor::rgba(0, 0, 0, 140), label);
        ctx.text(lx, ly, 1, pal::TEXT, label);
        ctx.region(id, lr(tx, tab_y, tw, 18));
        tx += tw + gap;
    }

    let modern = matches!(
        active,
        SettingsTab::Shaders | SettingsTab::Qol | SettingsTab::FairPlay | SettingsTab::Controls
    );
    if modern {
        let panel_w = 348.min(ctx.w - 8).max(8);
        let panel_x = cx - panel_w / 2;
        ctx.panel(panel_x, 54, panel_w, (ctx.h - 92).max(8));
        ctx.fill(panel_x + 1, 55, panel_w - 2, 2, pal::ACCENT);
        ctx.text(panel_x + 12, 62, 1, pal::ACCENT, "MEGU ENHANCED");
    }

    // Reserve the footer strip: any tab content that would reach it is
    // dropped by the widget helpers rather than painted under Done.
    ctx.band_top = ctx.h - 32;
    let base_y0 = if modern {
        if ctx.h < 300 { 76 } else { 82 }
    } else {
        56
    };
    let scroll = match active {
        SettingsTab::Video => ctx.state.menu_scroll.settings_video,
        SettingsTab::Audio => ctx.state.menu_scroll.settings_audio,
        SettingsTab::Shaders => ctx.state.menu_scroll.settings_shaders,
        SettingsTab::Qol => ctx.state.menu_scroll.settings_qol,
        SettingsTab::FairPlay => ctx.state.menu_scroll.settings_fairplay,
        SettingsTab::Language => ctx.state.menu_scroll.settings_language,
        SettingsTab::Controls => ctx.state.menu_scroll.settings_controls,
    }
    .min(ctx.state.active_menu_scroll_limit(ctx.w, ctx.h)) as i32;
    let content_top = if modern {
        58
    } else {
        tab_y.map(|y| y + 20).unwrap_or(34)
    };
    ctx.clip_top = content_top;
    let y0 = base_y0 - scroll;
    match active {
        SettingsTab::Video => video_tab(ctx, y0),
        SettingsTab::Audio => audio_tab(ctx, y0),
        SettingsTab::Shaders => shaders_tab(ctx, y0),
        SettingsTab::Qol => qol_tab(ctx, y0),
        SettingsTab::FairPlay => fairplay_tab(ctx, y0),
        SettingsTab::Language => language_tab(ctx, y0),
        SettingsTab::Controls => controls_tab(ctx, y0),
    }
    ctx.clip_top = 0;

    // Vanilla-style scrollbar chrome for the scrollable content viewport.
    // It is passive (wheel/keyboard owns scrolling) but gives the player
    // the same spatial cue as vanilla's settings lists.
    let max_scroll = ctx.state.active_menu_scroll_limit(ctx.w, ctx.h) as i32;
    if max_scroll > 0 {
        let track_x = ctx.w - 7;
        let track_y = content_top + 2;
        let track_h = (ctx.band_top - 4 - track_y).max(0);
        if track_h >= 18 {
            ctx.fill(track_x, track_y, 4, track_h, UiColor::rgba(0, 0, 0, 110));
            ctx.border(track_x, track_y, 4, track_h, pal::PANEL_BORDER);
            let thumb_h = ((track_h * track_h) / (track_h + max_scroll)).clamp(8, track_h);
            let travel = (track_h - thumb_h).max(1);
            let thumb_y = track_y + scroll * travel / max_scroll.max(1);
            ctx.fill(track_x + 1, thumb_y, 2, thumb_h, pal::TEXT_DIM);
        }
    }
    ctx.band_top = i32::MAX;

    // Footer buttons: adaptive row that compresses (then stacks) on
    // narrow logical widths instead of clipping off the left edge. The
    // mistake-proof session toolbar (Undo / Redo / Discard / Reset)
    // joins the row while all seven buttons still fit.
    let labels = [
        (WidgetId::SettingsDone, tr(lang, "Done", "完了"), true),
        (
            WidgetId::SettingsMods,
            tr(lang, "Mod Packs", "Modとパック"),
            true,
        ),
        (
            WidgetId::SettingsAboutMegu,
            tr(lang, "About", "Megu情報"),
            true,
        ),
        (
            WidgetId::SettingsUndo,
            tr(lang, "Undo", "元に戻す"),
            !ctx.state.settings_tx.undo_stack.is_empty(),
        ),
        (
            WidgetId::SettingsRedo,
            tr(lang, "Redo", "やり直す"),
            !ctx.state.settings_tx.redo_stack.is_empty(),
        ),
        (
            WidgetId::SettingsDiscard,
            tr(lang, "Discard", "破棄"),
            ctx.state.is_session_dirty(),
        ),
        (
            WidgetId::SettingsResetDefaults,
            tr(lang, "Defaults", "初期値"),
            true,
        ),
    ];
    let gap = 4;
    let bw7 = 100.min((ctx.w - 16 - gap * 6) / 7);
    if bw7 >= 40 {
        let total = bw7 * 7 + gap * 6;
        let mut bx = cx - total / 2;
        for (id, label, enabled) in labels {
            ctx.button_unchecked(id, lr(bx, ctx.h - 30, bw7, 20), label, enabled);
            bx += bw7 + gap;
        }
        return;
    }
    let bw = 100.min((ctx.w - 16 - gap * 2) / 3);
    let total = bw * 3 + gap * 2;
    if total <= ctx.w - 4 {
        let mut bx = cx - total / 2;
        for (id, label, _) in &labels[..3] {
            ctx.button_unchecked(*id, lr(bx, ctx.h - 30, bw, 20), label, true);
            bx += bw + gap;
        }
    } else if ctx.h >= 96 {
        // Two rows: Done on top, Mods/About below. Only used when the
        // window has room for both rows to stay clear of the tab strip.
        let bw2 = 100.min((ctx.w - 16 - gap) / 2).max(6);
        let half = bw2 * 2 + gap;
        let y1 = ctx.h - 52;
        ctx.button_unchecked(
            WidgetId::SettingsDone,
            lr(cx - bw2 / 2, y1, bw2, 20),
            labels[0].1,
            true,
        );
        let mut bx = cx - half / 2;
        for (id, label, _) in &labels[1..3] {
            ctx.button_unchecked(*id, lr(bx, y1 + 24, bw2, 20), label, true);
            bx += bw2 + gap;
        }
    } else {
        // Too short and too narrow for all three: Done alone remains
        // the exit path (Escape still navigates back as well).
        let bw = 100.min(ctx.w - 8).max(8);
        ctx.button_unchecked(
            WidgetId::SettingsDone,
            lr(cx - bw / 2, ctx.h - 30, bw, 20),
            labels[0].1,
            true,
        );
    }
}

